<?php
/** Cinematic official athlete profile; missing tournament data stays blank. */
$this->title=$model->name;
?>
<a class="back-link" href="/players">← 球员名单 / 球员资料</a>
<section class="athlete-stage" data-media><span class="athlete-watermark" aria-hidden="true"><?= e($model->team?->code) ?></span><div class="athlete-copy"><span class="eyebrow">世界杯球员 / <?= e($model->position) ?></span><h1><?= e($model->name) ?></h1><p><?= \app\services\TeamUi::label($model->team) ?> · <?= e($model->club?:'俱乐部未公布') ?></p><div class="hero-actions"><a class="button lime" href="/teams/<?= e($model->team?->slug) ?>">查看国家队 ↗</a><a href="/profile">关注球员 →</a></div></div><?php if($model->photo_url): ?><img class="athlete-portrait" src="<?= e(safe_url($model->displayPhotoUrl)) ?>" alt="<?= e($model->name_original) ?> · FIFA 官方照片" fetchpriority="high" referrerpolicy="no-referrer"><?php endif ?><span class="athlete-shirt"><?= (int)$model->shirt_number ?><small>球衣号码</small></span></section>
<?= $this->render('_source',['model'=>$model]) ?>
<div class="facts-grid"><?php foreach(['birth_date'=>'出生日期','height_cm'=>'身高 / cm','caps'=>'国家队出场','goals'=>'国家队进球'] as $key=>$label): ?><div><small><?= e($label) ?></small><b><?= $model->$key===null?'—':e($model->$key) ?></b></div><?php endforeach ?></div>
<section class="section"><h2>球员档案</h2><div class="datagrid athlete-datagrid"><?php foreach(['name_original'=>'原名','club'=>'效力俱乐部','position'=>'场上位置','birth_date'=>'出生日期'] as $key=>$name): ?><div class="datagrid-item"><div class="datagrid-title"><?= e($name) ?></div><div class="datagrid-content"><?= e($key==='position'?(['GK'=>'守门员','DF'=>'后卫','MF'=>'中场','FW'=>'前锋'][$model->$key]??$model->$key):($model->$key?:'—')) ?></div></div><?php endforeach ?></div></section>
<?php $records=\app\models\MatchLineup::find()->with('player')->where(['player_id'=>$model->id])->andWhere(['not',['official_import_id'=>null]])->all(); ?>
<?php if($records): ?><section class="section"><h2>本届比赛名单</h2><div class="lineup-history"><?php foreach($records as $line): ?><?php $game=\app\models\MatchGame::find()->with(['homeTeam','awayTeam'])->where(['id'=>$line->match_id])->one(); ?><?php if($game): ?><a href="/matches/<?= (int)$game->id ?>"><time><?= e(date('m.d',strtotime($game->starts_at))) ?></time><span><?= \app\services\TeamUi::label($game->homeTeam) ?><b><?= (int)$game->home_score ?> : <?= (int)$game->away_score ?></b><?= \app\services\TeamUi::label($game->awayTeam) ?></span><small><?= $line->is_starting_xi?'首发':'替补名单' ?> · <?= e($game->stage) ?></small></a><?php endif ?><?php endforeach ?></div></section><?php endif ?>
